const cp = require('node:child_process');
const win = process.platform === 'win32';
const target = 'tests/unit/luBootstrapProofScriptsIsolation.test.ts';
const r = cp.spawnSync(win ? 'npx.cmd' : 'npx', ['prettier', '--check', target], { encoding: 'utf8', shell: win });
if (r.error) { console.error('HARNESS: could not run prettier: ' + r.error.message); process.exit(2); }
if (r.status === 0) { console.log('OK: prettier reports ' + target + ' already formatted'); process.exit(0); }
if (r.status === 1) { console.error('VIOLATION: prettier flags formatting issues in ' + target); process.exit(1); }
console.error('HARNESS: unexpected prettier exit ' + r.status + '; stderr=' + String(r.stderr).slice(0, 300));
process.exit(2);

const fs = require('node:fs');
const files = [
  'scripts/dev-helpers/devgov-helper.mjs',
  'scripts/dev-helpers/lib/unitLint.mjs',
  'scripts/dev-helpers/lib/preflight.mjs',
  'scripts/dev-helpers/lib/importClosure.mjs',
];
const present = files.filter((f) => fs.existsSync(f));
if (present.length === 0) { console.error('VIOLATION: no dev-helpers tooling exists on this tree'); process.exit(1); }
if (present.length === files.length) { console.log('OK: dev-helpers tooling fully present (' + files.length + ' files)'); process.exit(0); }
console.error('HARNESS: partial presence, unexpected: ' + present.join(', '));
process.exit(2);

